<script lang="ts">
  import AuditValue from './AuditValue.svelte';
  import type { Candidate, CandidateMetric, MetricKind } from '../lib/types';

  export let kind: MetricKind;
  export let icon: string;
  export let items: CandidateMetric[];
  export let candidates: Candidate[];
  export let note = '';
  export let projectionWarning = '';

  $: candidateById = new Map(candidates.map((candidate) => [candidate.id, candidate]));
</script>

<article class="stat-tile kind-{kind.toLowerCase().replaceAll(' ', '-')}" data-kind={kind}>
  <header>
    <span class="tile-icon" aria-hidden="true">{icon}</span>
    <span class="kind-chip">{kind}</span>
  </header>
  <div class="tile-values">
    {#each items as item}
      <div class="tile-row">
        <span>{candidateById.get(item.candidate_id)?.short_name ?? item.candidate_id}</span>
        <AuditValue metric={item.value} showRange={kind !== 'Publicado'} compact />
      </div>
    {/each}
  </div>
  {#if note}<p>{note}</p>{/if}
  {#if projectionWarning}<small class="projection-warning">{projectionWarning}</small>{/if}
</article>

